TOOLS_BY_NAME = {t["name"]: t for t in TOOLS}


def schemas() -> list[dict[str, Any]]:
    """The subset of fields providers need (name/description/parameters)."""
    return [
        {"name": t["name"], "description": t["description"], "parameters": t["parameters"]}
        for t in TOOLS
    ]

